-- Разбор номенклатуры iiko: позиции, которые Тандем не переносит в новую программу (ответ Раисы 24.11.2026,
-- файл «Разбор номенклатуры iiko - ответ Раисы 2026-11-24.xlsx»: из 3 338 строк оставлено 2 106, удалено 1 232).
-- Снимаются 1217: из удалённых не снимаются 15, пока Тандем не ответит, - «Фрикадельки куриные» (2557) есть в
-- меню бота, остальные 14 входят в действующие техкарты оставленных блюд (полуфабрикаты «… фабрика», «Морковча»,
-- «Чай Симба 0,5», «Печенье крендельки»).
-- Нужна миграция 0069 (off_reason): без неё перенос из iiko включил бы позиции обратно.
-- Только рабочая база. Повторный прогон ничего не меняет. Вернуть всё: update tandem.items set active = true,
-- off_reason = null, off_at = null where off_reason like 'Разбор номенклатуры 24.11.2026%';
begin;
create temp table off_ids (iiko_id uuid primary key) on commit drop;
update tandem.items i set active = false,
       off_reason = 'Разбор номенклатуры 24.11.2026: Тандем не переносит (ответ Раисы)', off_at = now()
  from off_ids o
 where i.iiko_id = o.iiko_id and i.off_reason is null;
commit;
